def transform(grid):
    h, w = len(grid), len(grid[0])
    row_seps = [r for r in range(h) if all(v == 8 for v in grid[r])]
    col_seps = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]

    def segments(length, separators):
        out, start = [], 0
        for sep in separators:
            if start < sep:
                out.append(list(range(start, sep)))
            start = sep + 1
        if start < length:
            out.append(list(range(start, length)))
        return out

    rows, cols = segments(h, row_seps), segments(w, col_seps)
    cell_color = [[0 for _ in cols] for _ in rows]
    full_h, full_w = max(map(len, rows)), max(map(len, cols))
    points = {2: [], 3: []}
    for ri, rr in enumerate(rows):
        for ci, cc in enumerate(cols):
            if len(rr) != full_h or len(cc) != full_w:
                continue
            for r in rr:
                for c in cc:
                    if grid[r][c] in points:
                        points[grid[r][c]].append((ri, ci))
    for color, pts in points.items():
        for i, (r1, c1) in enumerate(pts):
            cell_color[r1][c1] = color if cell_color[r1][c1] == 0 else 6
            for r2, c2 in pts[i + 1:]:
                if r1 == r2:
                    cells = ((r1, c) for c in range(min(c1,c2), max(c1,c2)+1))
                elif c1 == c2:
                    cells = ((r, c1) for r in range(min(r1,r2), max(r1,r2)+1))
                else:
                    continue
                for r, c in cells:
                    cell_color[r][c] = color if cell_color[r][c] in (0,color) else 6
    out = [[0 for _ in range(w)] for _ in range(h)]
    for r in row_seps: out[r] = [8] * w
    for c in col_seps:
        for r in range(h): out[r][c] = 8
    for ri, rr in enumerate(rows):
        for ci, cc in enumerate(cols):
            if len(rr) != full_h or len(cc) != full_w: continue
            for r in rr:
                for c in cc: out[r][c] = cell_color[ri][ci]
    return out
